From 7cb5609659d721c3656fc30644d94ae895481462 Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Tue, 24 Nov 2026 21:27:43 +0100
Subject: [PATCH] Applet: add setDestroyed() to remove and bring back applets
 quietly

The only way to remove an applet without deleting it was its remove
action, which also shows a notification to undo it. This makes that
available as API, so the shell can undo and redo edit mode changes.

BUG: 482150
---
 src/plasma/applet.cpp           | 17 +++++++++
 src/plasma/applet.h             | 11 ++++++
 src/plasma/private/applet_p.cpp | 66 +++++++++++++++++++--------------
 src/plasma/private/applet_p.h   |  2 +
 4 files changed, 68 insertions(+), 28 deletions(-)

diff --git a/src/plasma/applet.cpp b/src/plasma/applet.cpp
index dd2a9f667..5ecd26757 100644
--- a/src/plasma/applet.cpp
+++ b/src/plasma/applet.cpp
@@ -229,6 +229,23 @@ bool Applet::destroyed() const
     return d->transient;
 }

+void Applet::setDestroyed(bool destroyed)
+{
+    if (d->transient == destroyed) {
+        return;
+    }
+
+    if (destroyed) {
+        if (immutability() != Types::Mutable || !d->started) {
+            return;
+        }
+        d->setDestroyed(true);
+        d->removeFromContainment();
+    } else {
+        d->undoDestroy();
+    }
+}
+
 KConfigLoader *Applet::configScheme() const
 {
     if (!d->configLoader) {
diff --git a/src/plasma/applet.h b/src/plasma/applet.h
index 5545988fc..3e90ff721 100644
--- a/src/plasma/applet.h
+++ b/src/plasma/applet.h
@@ -869,6 +869,17 @@ public Q_SLOTS:
      */
     void destroy();

+    /*!
+     * Removes the applet from its containment without deleting it, like its
+     * remove action does but without a notification, or brings it back when
+     * \a destroyed is false. An applet that is still destroyed is deleted by
+     * destroy() or on the next start.
+     *
+     * \sa destroyed()
+     * \since 6.9
+     */
+    void setDestroyed(bool destroyed);
+
     /*!
      * sets the status for this applet
      * \since 4.4
diff --git a/src/plasma/private/applet_p.cpp b/src/plasma/private/applet_p.cpp
index 37297d115..28eed422f 100644
--- a/src/plasma/private/applet_p.cpp
+++ b/src/plasma/private/applet_p.cpp
@@ -245,29 +245,8 @@ void AppletPrivate::askDestroy()
         }

         KNotificationAction *undoAction = deleteNotification->addAction(i18n("Undo"));
-        QObject::connect(undoAction, &KNotificationAction::activated, q, [=, this]() {
-            setDestroyed(false);
-            if (q->containment() && q->containment() != q) {
-                Plasma::Applet *containmentApplet = static_cast<Plasma::Applet *>(q->containment());
-                if (containmentApplet && containmentApplet->d->transient) {
-                    Q_EMIT containmentApplet->destroyedChanged(false);
-                    // when an applet gets transient, it's "systemimmutable"
-                    Q_EMIT q->immutabilityChanged(q->immutability());
-                }
-
-                // make sure the applets are sorted by id
-                auto position =
-                    std::lower_bound(q->containment()->d->applets.begin(), q->containment()->d->applets.end(), q, [](Plasma::Applet *a1, Plasma::Applet *a2) {
-                        return a1->id() < a2->id();
-                    });
-                Q_EMIT q->containment()->appletAboutToBeAdded(q, QRectF());
-                q->containment()->d->applets.insert(position, q);
-                Q_EMIT q->containment()->appletAdded(q, QRectF());
-                Q_EMIT q->containment()->appletsChanged();
-            }
-            if (deleteNotification) {
-                deleteNotification->close();
-            }
+        QObject::connect(undoAction, &KNotificationAction::activated, q, [this]() {
+            undoDestroy();
         });
         QObject::connect(deleteNotification.data(), &KNotification::closed, q, [this]() {
             // If the timer still exists, it means the undo action was NOT triggered
@@ -283,12 +262,43 @@ void AppletPrivate::askDestroy()
         });

         deleteNotification->sendEvent();
-        if (q->containment() && q->containment() != q) {
-            Q_EMIT q->containment()->appletAboutToBeRemoved(q);
-            q->containment()->d->applets.removeAll(q);
-            Q_EMIT q->containment()->appletRemoved(q);
-            Q_EMIT q->containment()->appletsChanged();
+        removeFromContainment();
+    }
+}
+
+void AppletPrivate::removeFromContainment()
+{
+    if (q->containment() && q->containment() != q) {
+        Q_EMIT q->containment()->appletAboutToBeRemoved(q);
+        q->containment()->d->applets.removeAll(q);
+        Q_EMIT q->containment()->appletRemoved(q);
+        Q_EMIT q->containment()->appletsChanged();
+    }
+}
+
+void AppletPrivate::undoDestroy()
+{
+    setDestroyed(false);
+    if (q->containment() && q->containment() != q) {
+        Plasma::Applet *containmentApplet = static_cast<Plasma::Applet *>(q->containment());
+        if (containmentApplet && containmentApplet->d->transient) {
+            Q_EMIT containmentApplet->destroyedChanged(false);
+            // when an applet gets transient, it's "systemimmutable"
+            Q_EMIT q->immutabilityChanged(q->immutability());
         }
+
+        // make sure the applets are sorted by id
+        auto position =
+            std::lower_bound(q->containment()->d->applets.begin(), q->containment()->d->applets.end(), q, [](Plasma::Applet *a1, Plasma::Applet *a2) {
+                return a1->id() < a2->id();
+            });
+        Q_EMIT q->containment()->appletAboutToBeAdded(q, QRectF());
+        q->containment()->d->applets.insert(position, q);
+        Q_EMIT q->containment()->appletAdded(q, QRectF());
+        Q_EMIT q->containment()->appletsChanged();
+    }
+    if (deleteNotification) {
+        deleteNotification->close();
     }
 }

