new file mode 100644
index 0000000000..c428f08e31
--- /dev/null
+++ b/shell/editmodehistory.cpp
@@ -0,0 +1,328 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#include "editmodehistory.h"
+
+#include <QAction>
+#include <QGuiApplication>
+#include <QQuickItem>
+#include <QTimer>
+#include <QUndoCommand>
+
+#include <KConfigLoader>
+#include <KLocalizedString>
+
+#include <Plasma/Containment>
+#include <Plasma/Corona>
+#include <PlasmaQuick/AppletQuickItem>
+
+using namespace Qt::StringLiterals;
+
+namespace
+{
+// Applets are hidden rather than deleted, so that they can be brought back as they were
+class AppletCommand : public QUndoCommand
+{
+public:
+    AppletCommand(EditModeHistory *history, Plasma::Applet *applet, bool added)
+        : m_history(history)
+        , m_applet(applet)
+        , m_added(added)
+    {
+    }
+
+    void undo() override
+    {
+        apply(m_added);
+    }
+
+    void redo() override
+    {
+        // The change was already made when it's recorded
+        if (m_recorded) {
+            m_recorded = false;
+            return;
+        }
+        apply(!m_added);
+    }
+
+private:
+    void apply(bool destroyed)
+    {
+        if (!m_applet) {
+            setObsolete(true);
+            return;
+        }
+        m_history->setAppletDestroyed(m_applet, destroyed);
+    }
+
+    EditModeHistory *const m_history;
+    const QPointer<Plasma::Applet> m_applet;
+    const bool m_added;
+    bool m_recorded = true;
+};
+
+class LayoutCommand : public QUndoCommand
+{
+public:
+    LayoutCommand(EditModeHistory *history, Plasma::Containment *containment, const QMap<QString, QString> &before, const QMap<QString, QString> &after)
+        : m_history(history)
+        , m_containment(containment)
+        , m_before(before)
+        , m_after(after)
+    {
+    }
+
+    void undo() override
+    {
+        apply(m_before);
+    }
+
+    void redo() override
+    {
+        if (m_recorded) {
+            m_recorded = false;
+            return;
+        }
+        apply(m_after);
+    }
+
+private:
+    void apply(const QMap<QString, QString> &layout)
+    {
+        if (!m_containment || m_containment->destroyed()) {
+            setObsolete(true);
+            return;
+        }
+        m_history->applyLayout(m_containment, layout);
+    }
+
+    EditModeHistory *const m_history;
+    const QPointer<Plasma::Containment> m_containment;
+    const QMap<QString, QString> m_before;
+    const QMap<QString, QString> m_after;
+    bool m_recorded = true;
+};
+
+// Both the panel's widget order ("12;15;13") and the desktop's widget geometries ("12:x,y,w,h,r;15:…") start with the applet ids
+QSet<QString> appletIds(const QMap<QString, QString> &layout)
+{
+    QSet<QString> ids;
+    for (const QString &value : layout) {
+        const auto items = value.split(u';', Qt::SkipEmptyParts);
+        for (const QString &item : items) {
+            ids.insert(item.section(u':', 0, 0));
+        }
+    }
+    return ids;
+}
+
+bool isPanel(Plasma::Containment *containment)
+{
+    return containment->containmentType() == Plasma::Containment::Type::Panel || containment->containmentType() == Plasma::Containment::Type::CustomPanel;
+}
+}
+
+EditModeHistory::EditModeHistory(Plasma::Corona *corona)
+    : QObject(corona)
+    , m_corona(corona)
+{
+    auto *undoAction = new QAction(QIcon::fromTheme(u"edit-undo-symbolic"_s), i18nc("@action:button", "Undo"), this);
+    undoAction->setEnabled(false);
+    connect(&m_stack, &QUndoStack::canUndoChanged, undoAction, &QAction::setEnabled);
+    connect(undoAction, &QAction::triggered, this, [this]() {
+        checkpoint();
+        m_stack.undo();
+    });
+    m_corona->setAction(u"undo"_s, undoAction);
+
+    auto *redoAction = new QAction(QIcon::fromTheme(u"edit-redo-symbolic"_s), i18nc("@action:button", "Redo"), this);
+    redoAction->setEnabled(false);
+    connect(&m_stack, &QUndoStack::canRedoChanged, redoAction, &QAction::setEnabled);
+    connect(redoAction, &QAction::triggered, this, [this]() {
+        checkpoint();
+        m_stack.redo();
+    });
+    m_corona->setAction(u"redo"_s, redoAction);
+
+    connect(m_corona, &Plasma::Corona::containmentAdded, this, &EditModeHistory::containmentAdded);
+    connect(m_corona, &Plasma::Corona::editModeChanged, this, &EditModeHistory::editModeChanged);
+    // The desktop saves widget geometries with a config sync
+    connect(m_corona, &Plasma::Corona::configSynced, this, &EditModeHistory::checkpoint);
+}
+
+void EditModeHistory::setAppletDestroyed(Plasma::Applet *applet, bool destroyed)
+{
+    m_applying = true;
+    applet->setDestroyed(destroyed);
+    m_applying = false;
+
+    m_hiddenApplets.removeAll(applet);
+    m_removedApplets.removeAll(applet);
+    if (applet->destroyed()) {
+        m_hiddenApplets.append(applet);
+    }
+}
+
+void EditModeHistory::applyLayout(Plasma::Containment *containment, const QMap<QString, QString> &layout)
+{
+    QQuickItem *containmentItem = PlasmaQuick::AppletQuickItem::itemForApplet(containment);
+    if (!containmentItem) {
+        return;
+    }
+
+    m_applying = true;
+    KConfigGroup config = containment->config();
+    bool geometriesChanged = false;
+    for (auto it = layout.cbegin(); it != layout.cend(); ++it) {
+        if (it.key() == u"AppletOrder") {
+            QList<int> order;
+            const auto ids = it.value().split(u';', Qt::SkipEmptyParts);
+            for (const QString &id : ids) {
+                order.append(id.toInt());
+            }
+            QMetaObject::invokeMethod(containmentItem, "reorderApplets", Q_ARG(QVariant, QVariant::fromValue(order)));
+        } else {
+            config.writeEntry(it.key(), it.value());
+            geometriesChanged = true;
+        }
+    }
+    if (geometriesChanged) {
+        QMetaObject::invokeMethod(containmentItem, "reloadLayout");
+    }
+    m_layouts.insert(containment, layoutOf(containment));
+    m_applying = false;
+}
+
+void EditModeHistory::containmentAdded(Plasma::Containment *containment)
+{
+    if (containment->containmentType() == Plasma::Containment::Type::CustomEmbedded) {
+        return;
+    }
+
+    connect(containment, &QObject::destroyed, this, [this, containment]() {
+        m_layouts.remove(containment);
+        m_newPanels.remove(containment);
+    });
+    connect(containment, &Plasma::Containment::appletCreated, this, [this](Plasma::Applet *applet) {
+        if (!m_corona->isEditMode() || m_applying || m_newPanels.contains(applet->containment())) {
+            return;
+        }
+        pushAppletChange(applet, true);
+    });
+    connect(containment, &Plasma::Containment::appletRemoved, this, [this](Plasma::Applet *applet) {
+        if (!m_corona->isEditMode() || m_applying || !applet->destroyed()) {
+            return;
+        }
+        m_removedApplets.append(applet);
+        pushAppletChange(applet, false);
+    });
+    // Brought back with the Undo button of its notification
+    connect(containment, &Plasma::Containment::appletAdded, this, [this](Plasma::Applet *applet) {
+        if (!m_corona->isEditMode() || m_applying || !m_removedApplets.removeAll(applet)) {
+            return;
+        }
+        pushAppletChange(applet, true);
+    });
+    if (KConfigLoader *configScheme = containment->configScheme()) {
+        // The panel saves its widget order this way
+        connect(configScheme, &KCoreConfigSkeleton::configChanged, this, &EditModeHistory::checkpoint);
+    }
+
+    if (!isPanel(containment)) {
+        return;
+    }
+    connect(containment, &Plasma::Applet::destroyedChanged, this, [this, containment](bool destroyed) {
+        if (!m_corona->isEditMode() || m_applying) {
+            return;
+        }
+        pushAppletChange(containment, !destroyed);
+    });
+    if (m_corona->isEditMode() && !m_applying) {
+        // Panels added from a template come with their widgets: adding all of them is a single change
+        m_newPanels.insert(containment);
+        QTimer::singleShot(0, this, [this, containment]() {
+            m_newPanels.remove(containment);
+        });
+        pushAppletChange(containment, true);
+    }
+}
+
+void EditModeHistory::editModeChanged(bool edit)
+{
+    m_stack.clear();
+    m_layouts.clear();
+    m_removedApplets.clear();
+
+    if (edit) {
+        const auto containments = m_corona->containments();
+        for (Plasma::Containment *containment : containments) {
+            m_layouts.insert(containment, layoutOf(containment));
+        }
+        return;
+    }
+
+    const auto hiddenApplets = std::exchange(m_hiddenApplets, {});
+    for (Plasma::Applet *applet : hiddenApplets) {
+        if (applet && applet->destroyed()) {
+            applet->destroy();
+        }
+    }
+}
+
+void EditModeHistory::pushAppletChange(Plasma::Applet *applet, bool added)
+{
+    // Record any pending widget move first, so it stays a separate change
+    checkpoint();
+    m_stack.push(new AppletCommand(this, applet, added));
+}
+
+void EditModeHistory::checkpoint()
+{
+    // Layouts are also saved in the middle of dragging a widget: wait for the drag to end
+    if (!m_corona->isEditMode() || m_applying || QGuiApplication::mouseButtons() != Qt::NoButton) {
+        return;
+    }
+
+    const auto containments = m_corona->containments();
+    for (Plasma::Containment *containment : containments) {
+        if (containment->containmentType() == Plasma::Containment::Type::CustomEmbedded || containment->destroyed()) {
+            continue;
+        }
+        const QMap<QString, QString> layout = layoutOf(containment);
+        auto it = m_layouts.find(containment);
+        if (it == m_layouts.end()) {
+            m_layouts.insert(containment, layout);
+            continue;
+        }
+        if (it.value() == layout) {
+            continue;
+        }
+        // Widgets added or removed also change the layout, but that's part of adding or removing them
+        if (appletIds(it.value()) == appletIds(layout)) {
+            m_stack.push(new LayoutCommand(this, containment, it.value(), layout));
+        }
+        it.value() = layout;
+    }
+}
+
+QMap<QString, QString> EditModeHistory::layoutOf(Plasma::Containment *containment) const
+{
+    QMap<QString, QString> layout;
+    if (KConfigLoader *configScheme = containment->configScheme()) {
+        if (KConfigSkeletonItem *appletOrder = configScheme->findItemByName(u"AppletOrder"_s)) {
+            layout.insert(u"AppletOrder"_s, appletOrder->property().toString());
+        }
+    }
+    const KConfigGroup config = containment->config();
+    const QStringList keys = config.keyList();
+    for (const QString &key : keys) {
+        if (key.startsWith(u"ItemGeometries")) {
+            layout.insert(key, config.readEntry(key, QString()));
+        }
+    }
+    return layout;
+}
diff --git a/shell/editmodehistory.h b/shell/editmodehistory.h
new file mode 100644
index 0000000000..4bf648f286
--- /dev/null
+++ b/shell/editmodehistory.h
@@ -0,0 +1,55 @@
+/*
+    SPDX-FileCopyrightText: 2026 Niccolò Venerandi <niccolo@venerandi.com>
+
+    SPDX-License-Identifier: GPL-2.0-or-later
+*/
+
+#pragma once
+
+#include <QHash>
+#include <QList>
+#include <QMap>
+#include <QObject>
+#include <QPointer>
+#include <QSet>
+#include <QUndoStack>
+
+namespace Plasma
+{
+class Applet;
+class Containment;
+class Corona;
+}
+
+/*
+ * Undo and redo for the changes made in edit mode: adding and removing widgets
+ * and panels, and moving widgets. The history starts empty every time edit mode
+ * is entered; it's available through the "undo" and "redo" corona actions.
+ */
+class EditModeHistory : public QObject
+{
+    Q_OBJECT
+public:
+    explicit EditModeHistory(Plasma::Corona *corona);
+
+    void setAppletDestroyed(Plasma::Applet *applet, bool destroyed);
+    void applyLayout(Plasma::Containment *containment, const QMap<QString, QString> &layout);
+
+private:
+    void containmentAdded(Plasma::Containment *containment);
+    void editModeChanged(bool edit);
+    void pushAppletChange(Plasma::Applet *applet, bool added);
+    void checkpoint();
+    QMap<QString, QString> layoutOf(Plasma::Containment *containment) const;
+
+    Plasma::Corona *const m_corona;
+    QUndoStack m_stack;
+    QHash<Plasma::Containment *, QMap<QString, QString>> m_layouts;
+    // Applets hidden by undo or redo, deleted for good when leaving edit mode
+    QList<QPointer<Plasma::Applet>> m_hiddenApplets;
+    // Applets the user removed, so that bringing them back from the notification is recorded too
+    QList<QPointer<Plasma::Applet>> m_removedApplets;
+    // Panels just added, whose widgets come with them rather than as separate changes
+    QSet<Plasma::Containment *> m_newPanels;
+    bool m_applying = false;
